<?php

namespace Database\Factories;

use App\Models\Activity;
use App\Models\Destination;
use App\Models\Event;
use App\Models\Experience;
use App\Models\Media;
use Illuminate\Database\Eloquent\Factories\Factory;
use Illuminate\Support\Str;

/** @extends Factory<Media> */
class MediaFactory extends Factory
{
    protected $model = Media::class;

    // Exactly one parent is set (media_exactly_one_parent_check).
    // Virtual primary_*_id columns are generated by the database and never set here.
    public function definition(): array
    {
        return [
            'file_path' => 'media/seed/' . Str::uuid() . '.jpg',
            'mime_type' => 'image/jpeg',
            'file_size_bytes' => fake()->numberBetween(50_000, 2_000_000),
            'is_primary' => false,
            'sort_order' => 0,
            'destination_id' => Destination::factory(),
            'activity_id' => null,
            'event_id' => null,
            'experience_id' => null,
            'uploaded_by' => null,
        ];
    }

    public function primary(): static
    {
        return $this->state(['is_primary' => true]);
    }

    public function png(): static
    {
        return $this->state([
            'file_path' => 'media/seed/' . Str::uuid() . '.png',
            'mime_type' => 'image/png',
        ]);
    }

    public function webp(): static
    {
        return $this->state([
            'file_path' => 'media/seed/' . Str::uuid() . '.webp',
            'mime_type' => 'image/webp',
        ]);
    }

    public function forActivity(): static
    {
        return $this->state([
            'destination_id' => null,
            'activity_id' => Activity::factory(),
            'event_id' => null,
            'experience_id' => null,
        ]);
    }

    public function forEvent(): static
    {
        return $this->state([
            'destination_id' => null,
            'activity_id' => null,
            'event_id' => Event::factory(),
            'experience_id' => null,
        ]);
    }

    public function forExperience(): static
    {
        return $this->state([
            'destination_id' => null,
            'activity_id' => null,
            'event_id' => null,
            'experience_id' => Experience::factory(),
        ]);
    }
}